gen(){ curl -s -o assets/music/$1.mp3 -w "$1 %{http_code}\n" -X POST "https://api.elevenlabs.io/v1/music?output_format=mp3_44100_192" -H "xi-api-key: x" -H "Content-Type: application/json" -d "{\"prompt\":\"$2\",\"music_length_ms\":$3,\"force_instrumental\":true}"; }
gen m1_ouverture "Epic cinematic medieval orchestral overture for a historical documentary opening. Instrumental only. Starts with a solemn horn call and low strings over a hurdy-gurdy drone, builds with taiko and frame drums, choir-like pads without words, soaring full orchestra by 30 seconds, then a mysterious descending reverse swell at the end. 90 bpm, D minor." 50000
gen m3_batir "Cinematic medieval building montage score, instrumental only. Driving low strings ostinato, hammered dulcimer, tabor drum and taiko, hurdy-gurdy, growing sense of scale and determination, occasional tense suspense passages, heroic brass swells, 100 bpm, A minor. Suitable under documentary narration, no vocals." 210000
